/** 
 * Dequeues a writable input buffer, if available.
 * @param inputBuffer The buffer where the dequeued buffer data is stored.
 * @return Whether an input buffer is ready to be used.
 */
@EnsuresNonNullIf(expression="#1.data",result=true) public boolean maybeDequeueInputBuffer(DecoderInputBuffer inputBuffer){
  if (inputStreamEnded) {
    return false;
  }
  if (inputBufferIndex < 0) {
    inputBufferIndex = mediaCodec.dequeueInputBuffer(0);
    if (inputBufferIndex < 0) {
      return false;
    }
    try {
      inputBuffer.data = mediaCodec.getInputBuffer(inputBufferIndex);
      if (inputBuffer.data == null) {
        throw new IllegalStateException("Input buffer is null");
      }
      inputBuffer.clear();
      checkNotNull(inputBuffer.data);
    } catch (IllegalStateException | NullPointerException e) {
      // Log the exception and handle it gracefully
      e.printStackTrace();
      return false;
    }
  }
  return true;
}
